seed = bytes(range(32)); ctx = 'independent-audit-context'
bounds = [1, 2, 3, 7, 10, 17, 60, 1000, 2**31 + 1, 2**32 - 1, 2**32]
js = r"""
import {createRandomSource} from './packages/engine-adapter/dist/random.js';
const seed=Buffer.from(Array.from({length:32},(_,i)=>i)),s=createRandomSource(seed,process.argv[1]),bounds=JSON.parse(process.argv[2]),out=[];
for(let i=0;i<=250;i++){out.push(['float',i,s.random(i)]);for(const b of bounds)out.push(['integer',i,b,s.integer(i,b)]);for(const d of ['instance','match','game'])out.push(['identifier',i,d,s.identifier(d,i)]);}
